import { test, expect } from '@playwright/test';

test.describe('Notification Preferences Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/settings');
  });

  test('should successfully update notification preferences and save changes', async ({ page }) => {
    // Verify notification settings page is visible
    const settingsContainer = page.getByRole('region', { name: /settings/i });
    await expect(settingsContainer).toBeVisible();

    // Verify notification preferences section is visible
    const notificationSection = page.getByRole('region', { name: /notifications/i });
    await expect(notificationSection).toBeVisible();

    // Verify notification toggle button is visible and enabled
    const notificationToggle = page.getByRole('button', { name: /notifications/i });
    await expect(notificationToggle).toBeVisible();

    // Verify notification count is displayed
    const notificationCount = page.getByText(/notifications/i);
    await expect(notificationCount).toBeVisible();

    // Verify notification types are listed
    const notificationTypes = page.getByRole('list', { name: /notification types/i });
    await expect(notificationTypes).toBeVisible();

    // Verify all notification types are listed
    const notificationTypeItems = page.getByRole('listitem', { name: /notification types/i });
    const count = await notificationTypeItems.count();
    expect(count).toBeGreaterThan(0);

    // Verify settings are initially saved
    const settingsStatus = page.getByText(/saved/i);
    await expect(settingsStatus).toBeVisible();

    // Click notification toggle to enable notifications
    await notificationToggle.click();

    // Verify toggle is now active
    await expect(notificationToggle).toHaveAttribute('aria-pressed', 'true');

    // Verify notification count is updated
    await expect(notificationCount).toContainText('1');

    // Verify settings are still saved
    await expect(settingsStatus).toBeVisible();

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/notifications updated/i);
    await expect(successMessage).toBeVisible();

    // Verify settings are still saved
    await expect(settingsStatus).toBeVisible();
  });

  test('should handle invalid notification preferences and display error message', async ({ page }) => {
    // Verify notification settings page is visible
    const settingsContainer = page.getByRole('region', { name: /settings/i });
    await expect(settingsContainer).toBeVisible();

    // Verify notification preferences section is visible
    const notificationSection = page.getByRole('region', { name: /notifications/i });
    await expect(notificationSection).toBeVisible();

    // Verify notification toggle button is visible and enabled
    const notificationToggle = page.getByRole('button', { name: /notifications/i });
    await expect(notificationToggle).toBeVisible();

    // Verify notification count is displayed
    const notificationCount = page.getByText(/notifications/i);
    await expect(notificationCount).toBeVisible();

    // Verify notification types are listed
    const notificationTypeItems = page.getByRole('listitem', { name: /notification types/i });
    await expect(notificationTypeItems).toBeVisible();

    // Verify settings are initially saved
    const settingsStatus = page.getByText(/saved/i);
    await expect(settingsStatus).toBeVisible();

    // Click notification toggle to disable notifications
    await notificationToggle.click();

    // Verify toggle is now inactive
    await expect(notificationToggle).toHaveAttribute('aria-pressed', 'false');

    // Verify notification count is updated
    await expect(notificationCount).toContainText('0');

    // Verify settings are still saved
    await expect(settingsStatus).toBeVisible();

    // Click save button with invalid settings
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid settings/i);
    await expect(errorMessage).toBeVisible();

    // Verify settings are still saved
    await expect(settingsStatus).toBeVisible();
  });
});
